import{_ as i,c as n,a2 as r,o as t}from"./chunks/framework.rHWNTPhC.js";const g=JSON.parse('{"title":"Ergebnismeldung-Service","description":"","frontmatter":{},"headers":[],"relativePath":"services/ergebnismeldung-service/index.md","filePath":"services/ergebnismeldung-service/index.md"}'),a={name:"services/ergebnismeldung-service/index.md"};function l(d,e,s,h,o,u){return t(),n("div",null,e[0]||(e[0]=[r('<h1 id="ergebnismeldung-service" tabindex="-1">Ergebnismeldung-Service <a class="header-anchor" href="#ergebnismeldung-service" aria-label="Permalink to &quot;Ergebnismeldung-Service&quot;">​</a></h1><p>Service der Informationen und Operationen für die Ergebnisse einer Wahl bereitstellt. Dabei geht es um die Ergebnisse die durch den Nutzer anhand von Masken erfasst werden.</p><h2 id="abhangigkeiten" tabindex="-1">Abhängigkeiten <a class="header-anchor" href="#abhangigkeiten" aria-label="Permalink to &quot;Abhängigkeiten&quot;">​</a></h2><p>Folgende Services werden benötigt:</p><ul><li>Basisdaten-Service</li><li>Briefwahl-Service</li><li>EAI-Service</li><li>Infomanagement-Service</li><li>Monitoring-Service</li><li>Wahlvorbereitung-Service</li></ul><h2 id="daten-und-funktionen" tabindex="-1">Daten und Funktionen <a class="header-anchor" href="#daten-und-funktionen" aria-label="Permalink to &quot;Daten und Funktionen&quot;">​</a></h2><ul><li>Verwalten und Übermitteln von Ergebnismeldungen</li><li>Verwalten von A- und B-Werten</li></ul><h3 id="abrufen-von-a-werten-wahlberechtigte" tabindex="-1">Abrufen von A-Werten (Wahlberechtigte) <a class="header-anchor" href="#abrufen-von-a-werten-wahlberechtigte" aria-label="Permalink to &quot;Abrufen von A-Werten (Wahlberechtigte)&quot;">​</a></h3><p>Die Methode <code>getAWerte()</code> liefert die A-Werte für eine bestimmte Wahlbezirk-ID. Die A-Werte repräsentieren die Anzahl der Wahl- bzw. Stimmberechtigten in einem Wahlbezirk. Sie teilen sich auf in die Anzahl an Wahlberechtigten die keinen Wahlschein erhalten haben (A1) und in die Anzahl an Wahlberechtigten die einen Wahlschein erhalten haben und deshalb einen W-Vermerk im Wählerverzeichnis besitzen (A2).</p><ul><li>Wenn über die EAI im externen Wahlsystem Daten gefunden werden, dann werden diese im lokalen Repository gespeichert und zurück gegeben.</li><li>Sofern über die EAI im externen Wahlsystem keine Daten gefunden werden können, wird versucht auf &#39;alte&#39; A-Werte im lokalen Repository zuzugreifen.</li><li>Falls weder im externen Wahlsystem noch im lokalen Repository A-Werte gefunden werden liefert der Service einen Fehler.</li></ul><h3 id="initialisieren-von-a-werten-wahlberechtigte" tabindex="-1">Initialisieren von A-Werten (Wahlberechtigte) <a class="header-anchor" href="#initialisieren-von-a-werten-wahlberechtigte" aria-label="Permalink to &quot;Initialisieren von A-Werten (Wahlberechtigte)&quot;">​</a></h3><p>Die Methode initialisiereAWerte() initialisiert die Wahlberechtigten (A-Werte) für eine Liste an Wahlbezirk-IDs.</p><ul><li>Für jede Wahlbezirk-ID in der Liste wird über die EAI im externen Wahlsystem nach A-Werten gesucht. Bei Erfolg werden diese im lokalen Repository gespeichert.</li><li>Bei Nichterfolg, wird geprüft ob im lokalen Repository wenigstens &#39;alte&#39; A-Werte existieren.</li><li>Falls weder im externen Wahlsystem noch im lokalen Repository A-Werte gefunden werden liefert der Service einen Fehler.</li></ul><h3 id="update-des-status-der-ergebnisermittlung" tabindex="-1">Update des Status der Ergebnisermittlung <a class="header-anchor" href="#update-des-status-der-ergebnisermittlung" aria-label="Permalink to &quot;Update des Status der Ergebnisermittlung&quot;">​</a></h3><p>Bei der Auszählung (Ergebnisermittlung) wird zuerst eine Schnellmeldung vorbereitet. Den Abschluss der Auszählung bildet die Niederschrift. Die Schnellmeldung und die Niederschrift können gedruckt und übermittelt werden.</p><p>Welche Aktionen für die jeweiligen Dokumente bereits in einem Wahllokal vollzogen wurden, wird über den Status gepflegt.</p><p>Über Änderungen an dem Status wird auch der <a href="/Wahllokalsystem/services/monitoring-service/">Monitoring-Service</a> informiert.</p>',17)]))}const b=i(a,[["render",l]]);export{g as __pageData,b as default};
